"""Complete glomerular disease with lupus, complement, infection and inherited disease."""
from create_membranous_iga import rows,q,GD,IG
from qbank_authoring import ref,finalize
LN=ref('KDIGO 2024 Lupus Nephritis Guideline','https://kdigo.org/wp-content/uploads/2024/01/KDIGO-2024-Lupus-Nephritis-Guideline.pdf')
MP=ref('KDIGO Immunoglobulin/Complement-Mediated MPGN: Key Takeaways','https://kdigo.org/wp-content/uploads/2017/02/Key-Takeaways-ICMG-GD-GL-Clinicians.pdf')
MG=ref('IKMG Consensus: Evaluation of MGRS','https://pmc.ncbi.nlm.nih.gov/articles/PMC7136169/')
AL=ref('GeneReviews: Alport Syndrome','https://ncbi.nlm.nih.gov/books/NBK1207/')

q('Should systemic glucocorticoids be routinely prescribed solely to prevent nephritis in otherwise nonrenal IgA vasculitis?', 'No; renal-prevention benefit is not established for that routine strategy',[
 ('Yes, they reliably prevent all later renal disease','This is not supported.'),('No, therefore severe gastrointestinal or other IgAV disease can never need steroids','Other indications require a separate assessment.'),('Yes, and urinary monitoring can then stop','Renal monitoring remains important.')],
 'Prevention and treatment of established organ disease are different questions', '**IgAV kidney surveillance is necessary even after extrarenal symptoms improve.**', ['Check urine, BP and renal function as appropriate.','Treat established renal disease according to severity and evidence.'], '**Avoid a blanket prophylactic steroid rule.**', ['Specific severe extrarenal disease may have other treatment indications.','Discuss toxicity and the actual target.'], [['Nonrenal IgAV','No routine steroid solely for nephritis prevention'],['Renal disease','Severity-directed care'],['Monitoring','Continue']], [IG])
q('A patient with SLE develops persistent proteinuria above 500 mg/day and an active sediment. What is the most appropriate next principle?', 'Consider kidney biopsy to classify lupus nephritis and guide treatment',[
 ('Escalate solely from anti-dsDNA without assessing tissue or function','Serology alone does not fully classify renal pathology.'),('Assume every SLE renal abnormality is class V','Several renal lesions are possible.'),('Wait for nephrotic-range proteinuria in every case','Proliferative disease can be important at lower protein levels.')],
 'Clinical findings can underestimate histological severity', '**Biopsy identifies class, activity, chronicity and competing lesions.**', ['Quantify protein and assess GFR.','Complement and anti-dsDNA support the broader activity assessment.'], '**Use tissue when it changes the treatment plan.**', ['Assess procedural safety.','Rapid severe disease may require urgent treatment while evaluation proceeds.'], [['Trigger','Proteinuria/active sediment or dysfunction'],['Biopsy','Class and activity'],['Serology','Complementary']], [LN], 'clinical_scenario')
q('What does full-house immunofluorescence in a compatible kidney biopsy suggest?', 'Lupus nephritis, while recognizing that the pattern is not absolutely specific',[
 ('Anti-GBM disease as the classic pattern','That typically has linear IgG.'),('MCD as the classic pattern','MCD is generally negative by routine IF.'),('A unique diagnosis without any clinical correlation','Nonlupus full-house patterns can occur.')],
 'A deposit pattern is powerful but still contextual', '**Full-house refers to multiple immunoglobulin and complement staining components.**', ['Interpret with SLE clinical and serological evidence.','The distribution and microscopy define the class.'], '**Do not treat the staining label alone.**', ['Assess infection and other mimics when the context is atypical.','Classify activity and chronic damage.'], [['Pattern','IgG, IgA, IgM and complement components'],['Association','Strong lupus clue'],['Limit','Not perfectly specific']], [LN])
q('Proliferative lupus lesions involve at least half the sampled glomeruli. Which class is defined?', 'Class IV',[
 ('Class III','This is focal involvement of fewer than half.'),('Class II','This is mesangial proliferative disease without the stated diffuse pattern.'),('Class V alone','This is a membranous pattern rather than diffuse proliferative disease.')],
 'The fraction of glomeruli distinguishes focal from diffuse proliferative disease', '**Class IV involves at least 50% of glomeruli.**', ['Active and chronic lesions can coexist.','Class V can accompany proliferative lesions.'], '**Use activity and chronicity to interpret treatment potential.**', ['Reversible inflammation differs from established sclerosis.','A mixed class follows the clinically relevant proliferative pathway.'], [['Class III','Fewer than 50%'],['Class IV','At least 50%'],['Class V','Membranous component']], [LN])
q('Which initial treatment principle fits active class III/IV lupus nephritis under KDIGO 2024?', 'Glucocorticoids plus an appropriate immune regimen such as MPAA or low-dose IV cyclophosphamide, with selected combination options',[
 ('Glucocorticoids alone as adequate routine therapy for all active proliferative disease','Additional immunosuppression is recommended.'),('RAS blockade alone regardless of active destructive lesions','Supportive therapy does not replace immune control.'),('A CNI without considering kidney function or the rest of the regimen','CNI use is context-dependent.')],
 'Proliferative disease needs prompt inflammatory control', '**KDIGO includes MPAA, low-dose cyclophosphamide, belimumab combinations and selected MPAA-CNI regimens.**', ['Kidney function, extrarenal disease, adherence and fertility shape selection.','Use a steroid-minimizing taper when appropriate.'], '**Plan induction and maintenance together.**', ['Provide infection and reproductive safety counseling.','Track renal and systemic response.'], [['Base','Glucocorticoid plus immune treatment'],['Add-on options','Patient-specific'],['Supportive care','Continues alongside']], [LN])
q('After response to proliferative lupus nephritis, what is the preferred general maintenance principle?', 'Continue suitable maintenance immunosuppression, commonly MPAA, rather than stopping all therapy immediately',[
 ('Stop all treatment after one low protein result','Relapse risk persists.'),('Continue induction cyclophosphamide indefinitely','Cumulative toxicity makes this inappropriate.'),('Use no follow-up once complement normalizes','Serology alone does not establish lasting renal remission.')],
 'Clinical response is not the end of disease management', '**KDIGO recommends an adequate total duration, generally at least 36 months for initial and maintenance therapy together.**', ['Azathioprine is an alternative in selected settings, including pregnancy planning.','The exact regimen follows the response and prior combination strategy.'], '**Reassess before tapering.**', ['Review sustained remission, toxicity and preferences.','Consider biopsy in selected uncertain cases.'], [['Maintenance','Sustains response'],['Duration','Usually at least three years total'],['Taper','Individualized after reassessment']], [LN])
q('What role does hydroxychloroquine have in SLE with lupus nephritis when not contraindicated?', 'Background therapy with appropriate dose and retinal-safety monitoring',[
 ('It replaces all induction therapy for severe proliferative nephritis','It is background rather than sufficient sole treatment.'),('It is prohibited in every degree of CKD','Dose and monitoring need adjustment rather than a universal ban.'),('No retinal review is ever needed','Retinal toxicity precautions are important.')],
 'Renal disease is managed within systemic lupus care', '**KDIGO recommends hydroxychloroquine or an equivalent antimalarial when suitable.**', ['Body weight, kidney function and exposure affect safety planning.','Retinal screening follows the relevant guidance.'], '**Continue disease-specific renal treatment.**', ['Review adherence and interactions.','Do not use an antimalarial response as a substitute for renal monitoring.'], [['Role','Background SLE therapy'],['Safety','Dose/retinal assessment'],['Severe LN','Needs additional treatment']], [LN])
q('A woman with controlled lupus nephritis on mycophenolate is planning pregnancy. What is the best approach?', 'Arrange preconception disease and medication review, replacing teratogenic therapy with a suitable pregnancy-compatible plan before conception',[
 ('Continue mycophenolate unchanged because remission removes fetal risk','The drug remains teratogenic.'),('Stop every medicine abruptly without a replacement plan','Flare risk can endanger mother and fetus.'),('Wait until delivery to assess drug safety','Planning must occur earlier.')],
 'Maternal disease control and fetal safety must be coordinated', '**Pregnancy is best planned after stable disease control.**', ['Azathioprine and selected other agents can be used in suitable regimens.','RAS blockers and other renal medicines also need review.'], '**Coordinate nephrology, rheumatology and obstetric care.**', ['Discuss contraception during the transition.','Monitor for flare and pregnancy-related hypertensive disease.'], [['Before conception','Review disease and drugs'],['Mycophenolate','Replace through a safe plan'],['Follow-up','Multidisciplinary']], [LN], 'clinical_scenario')
q('Proteinuria persists after lupus treatment despite improved serology and stable GFR. What is the best interpretation?', 'Persistent proteinuria can reflect active disease, delayed recovery or chronic damage; assess the full trajectory and consider repeat biopsy when it changes care',[
 ('Every residual protein value proves active proliferative flare','Proteinuria is not uniquely an activity marker.'),('Normal complement guarantees no renal inflammation','Serology is imperfect.'),('Repeat biopsy can never provide useful information','It can distinguish activity from chronicity in selected cases.')],
 'Clinical and histological remission can diverge', '**Avoid automatic escalation without reassessing adherence, exposure and pathology.**', ['Chronic scarring may not improve with more immune toxicity.','Ongoing active lesions may require a revised regimen.'], '**Use objective response measures.**', ['Trend proteinuria, GFR and systemic findings.','Select repeat tissue assessment for a defined decision.'], [['Proteinuria','Several mechanisms'],['Serology','Supportive, imperfect'],['Biopsy','Can resolve activity/chronicity uncertainty']], [LN], 'clinical_scenario')
q('What does an MPGN pattern establish?', 'A morphological pattern requiring evaluation for immune-complex, monoclonal and complement-mediated causes',[
 ('One disease with one uniform treatment','The etiologies differ.'),('A mandatory infection in every case','Autoimmune and complement causes also occur.'),('Absence of glomerular basement-membrane remodeling','Double contours and remodeling are characteristic features.')],
 'Classify by mechanism rather than an old morphological type alone', '**IF findings help direct the work-up.**', ['Immunoglobulin-positive disease suggests immune-complex or monoclonal pathways.','Complement-dominant disease raises complement dysregulation and related differentials.'], '**Search for a treatable driver.**', ['Assess infection, autoimmunity and monoclonal proteins.','Complement investigations can be appropriate.'], [['Pattern','MPGN'],['IF','Guides mechanism'],['Cause','Determines treatment']], [MP])
q('Glomerular C3 staining is dominant over immunoglobulins. Which mechanism deserves focused assessment?', 'Alternative-complement pathway dysregulation, while excluding infection-related and other mimics',[
 ('Classic anti-GBM linear IgG disease','That has a different IF pattern.'),('A primary neuromuscular autoantibody process','This does not explain the renal lesion.'),('Complement staining proves no immune mechanism is present','Complement dysregulation is an immune pathway.')],
 'Complement dominance is a mechanistic clue', '**C3 glomerulopathy includes distinct EM patterns within a complement-driven category.**', ['Acquired autoantibodies and genetic factors can contribute.','Monoclonal proteins can drive complement abnormalities in selected adults.'], '**Use specialist etiological evaluation.**', ['Clinical course helps distinguish persistent disease from resolving infection-related GN.','Treatment selection follows the current disease-specific evidence and context.'], [['IF','C3 dominant'],['Mechanism','Alternative pathway'],['Work-up','Acquired/genetic/monoclonal contexts']], [MP])
q('Nephritic syndrome occurs two weeks after streptococcal pharyngitis, with low C3 and subepithelial humps. Which diagnosis is favored?', 'Postinfectious, classically poststreptococcal, glomerulonephritis',[
 ('Synpharyngitic primary IgAN','The delayed timing and complement pattern favor another diagnosis.'),('MCD','The nephritic deposit pattern differs.'),('Anti-GBM disease','Linear IgG rather than this immune-complex pattern is expected.')],
 'A latent interval and complement consumption support infection-related disease', '**Supportive care addresses BP, edema and kidney complications.**', ['Treat an ongoing relevant infection.','Persistent low complement or an atypical course needs reconsideration.'], '**Do not assume all postinfectious presentations are mild.**', ['Adults can have substantial AKI.','Biopsy may help atypical or severe cases.'], [['Timing','After a latent interval'],['C3','Often reduced'],['Course','Monitor recovery and complement']], [GD], 'clinical_scenario')
q('An older diabetic adult has active staphylococcal infection, AKI and IgA-dominant glomerular deposits. What is the key diagnostic concern?', 'IgA-dominant infection-related GN rather than automatic classification as primary IgAN',[
 ('IgA staining proves primary IgAN regardless of infection','The context changes the diagnosis.'),('Start immune suppression alone and ignore the infection','Infection control is essential.'),('Diabetes explains all renal findings without further assessment','The acute active sediment and biopsy need interpretation.')],
 'An immunoglobulin label does not remove the clinical cause', '**IgA-dominant GN can accompany active bacterial infection.**', ['Age, comorbidity and exudative biopsy findings can add support.','Primary IgAN and other lesions remain differential considerations.'], '**Prioritize source control and antimicrobial therapy.**', ['Immune treatment is not an automatic response to IgA deposits.','Assess complications and the subsequent renal course.'], [['Context','Active bacterial infection'],['Deposit','IgA dominant possible'],['Priority','Treat infection/source']], [GD], 'clinical_scenario')
q('A small plasma-cell clone produces a monoclonal immunoglobulin causing biopsy-proven kidney damage without myeloma-defining criteria. Which concept applies?', 'Monoclonal gammopathy of renal significance',[
 ('Harmless MGUS by definition because the clone is small','Organ toxicity makes the clone clinically significant.'),('Multiple myeloma is mandatory whenever any clone exists','Myeloma has separate defining criteria.'),('A monoclonal band alone proves every kidney lesion is caused by it','Biopsy and clinicopathological correlation are necessary.')],
 'Clone size does not determine renal toxicity', '**A nephrotoxic monoclonal protein can justify clone-directed evaluation and treatment.**', ['The renal lesion must be characterized and linked appropriately.','Serum and urine studies and marrow assessment refine the source.'], '**Coordinate hematology and nephrology.**', ['Avoid dismissing progressive renal injury from a small clone.','Also avoid attributing unrelated CKD to an incidental band.'], [['Small clone','Can be nephrotoxic'],['Kidney biopsy','Defines lesion'],['Treatment','Mechanism/clone-directed']], [MG], 'clinical_scenario')
q('Congo-red-positive renal deposits show apple-green birefringence. What is essential before choosing disease-directed therapy?', 'Accurate amyloid typing, preferably with validated specialized methods when needed',[
 ('Assume every case is AL because a monoclonal band is present','An incidental clone can coexist with another amyloid type.'),('Assume every case is AA because inflammation is present','Typing is still required.'),('Treat the stain as a complete etiological diagnosis','It establishes amyloid, not the precursor protein.')],
 'The deposit type determines the treatment', '**AL, AA and other amyloid diseases require different approaches.**', ['Expert pathology and mass-spectrometry-based typing can resolve uncertainty.','Assess systemic organ involvement.'], '**Do not give toxic clone-directed treatment from an untyped stain alone.**', ['Link the precursor and the clinical disease.','Coordinate the appropriate specialty pathway.'], [['Congo red','Amyloid confirmation'],['Typing','Precursor identity'],['Therapy','Type-specific']], [MG,GD])
q('Persistent hematuria, sensorineural hearing loss and a family history of kidney failure suggest which diagnosis?', 'Alport spectrum disease',[
 ('MCD','This does not explain the inherited auditory-renal pattern.'),('Pure poststreptococcal GN','The persistent familial phenotype differs.'),('Primary membranous nephropathy','The hereditary collagen phenotype is more characteristic.')],
 'The glomerular basement membrane has a genetic structural biology', '**COL4A3, COL4A4 and COL4A5 variants produce different inheritance patterns.**', ['Auditory and ocular manifestations can provide clues.','Not every affected person has all extrarenal features.'], '**Confirm genetically when appropriate.**', ['Provide kidney-protective care and family counseling.','Do not label all familial thin-basement-membrane findings as universally benign.'], [['Structure','Type IV collagen'],['Genes','COL4A3/4/5'],['Care','Protection and family assessment']], [AL], 'clinical_scenario')
q('A patient with diabetes develops abrupt nephrotic syndrome, active hematuria and rapid GFR loss. What is the best diagnostic principle?', 'Investigate superimposed or alternative glomerular disease rather than assuming ordinary diabetic kidney disease',[
 ('Diabetes excludes all other glomerulopathies','They can coexist.'),('A biopsy is prohibited solely because diabetes is present','It can be valuable in atypical presentations.'),('Every diabetic nephrotic syndrome requires immediate steroid treatment','The cause must be established.')],
 'A common disease must still fit the clinical course', '**Abrupt change and active sediment are reasons to reassess attribution.**', ['Retinopathy and diabetes duration provide context but are not perfect arbiters.','Medication, infection and systemic clues matter.'], '**Use a targeted investigation and tissue plan.**', ['Balance biopsy value and safety.','Treat the identified lesion while maintaining appropriate diabetes and cardiovascular care.'], [['Typical course','Often gradual'],['Atypical change','Broader differential'],['Biopsy','Can change treatment']], [GD], 'clinical_scenario')

if __name__=='__main__':finalize('Nephrology',3,'Glomerular Disease and Nephrotic Syndromes','neph-glomerular',rows,52)
